  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f3f6fb;
      --panel: rgba(255, 255, 255, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #0f172a;
      --muted: #475569;
      --primary: #2563eb;
      --primary-soft: rgba(37, 99, 235, 0.12);
      --shadow: 0 20px 45px rgba(15, 23, 42, 0.12);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top left, rgba(59, 130, 246, 0.16), transparent 32%),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.14), transparent 28%),
        var(--bg);
      color: var(--text);
    }

    .card {
      width: min(100%, 560px);
      padding: 36px;
      border-radius: var(--radius);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      padding: 8px 12px;
      border-radius: 999px;
      background: var(--primary-soft);
      color: var(--primary);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 18px 0 10px;
      font-size: clamp(1.9rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    p {
      margin: 0 0 28px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 24px;
    }

    .form-field {
      display: grid;
      gap: 14px;
    }

    .form-field legend {
      padding: 0;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .options {
      display: grid;
      gap: 12px;
    }

    .radio-option {
      position: relative;
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 16px 18px;
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 18px;
      background: #fff;
      cursor: pointer;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    .radio-option:hover {
      border-color: rgba(37, 99, 235, 0.34);
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.08);
      transform: translateY(-1px);
    }

    .radio-option input {
      position: absolute;
      opacity: 0;
      pointer-events: none;
    }

    .indicator {
      width: 20px;
      height: 20px;
      border: 2px solid #94a3b8;
      border-radius: 50%;
      display: grid;
      place-items: center;
      flex-shrink: 0;
      transition: border-color 0.2s ease, background-color 0.2s ease;
    }

    .indicator::after {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #fff;
      transform: scale(0);
      transition: transform 0.2s ease;
    }

    .option-copy {
      display: grid;
      gap: 2px;
    }

    .option-title {
      font-weight: 600;
    }

    .option-note {
      color: var(--muted);
      font-size: 0.92rem;
    }

    .radio-option:has(input:checked) {
      border-color: var(--primary);
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.16);
    }

    .radio-option:has(input:checked) .indicator {
      border-color: var(--primary);
      background: var(--primary);
    }

    .radio-option:has(input:checked) .indicator::after {
      transform: scale(1);
    }

    .radio-option:has(input:focus-visible) {
      outline: 3px solid rgba(37, 99, 235, 0.22);
      outline-offset: 2px;
    }

    button {
      width: fit-content;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, #2563eb, #1d4ed8);
      cursor: pointer;
      box-shadow: 0 16px 28px rgba(37, 99, 235, 0.28);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 20px 32px rgba(37, 99, 235, 0.32);
    }

    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.24);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5em;
      margin: 0;
      font-weight: 600;
      color: var(--primary);
    }

    @media (max-width: 640px) {
      .card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <main class="card">
    <span class="eyebrow">Profile settings</span>
    <h1>Choose your notification preference</h1>
    <p>Select the one channel you want us to use for updates and alerts.</p>

    <form id="notification-form">
      <div class="form-field">
        <fieldset>
          <legend>How do you prefer to receive notifications?</legend>
          <div class="options">
            <label class="radio-option">
              <input type="radio" name="notificationPreference" value="Email" required>
              <span class="indicator" aria-hidden="true"></span>
              <span class="option-copy">
                <span class="option-title">Email</span>
                <span class="option-note">Best for account updates and summaries.</span>
              </span>
            </label>

            <label class="radio-option">
              <input type="radio" name="notificationPreference" value="SMS">
              <span class="indicator" aria-hidden="true"></span>
              <span class="option-copy">
                <span class="option-title">SMS</span>
                <span class="option-note">Fast delivery for time-sensitive notices.</span>
              </span>
            </label>

            <label class="radio-option">
              <input type="radio" name="notificationPreference" value="Push Notifications">
              <span class="indicator" aria-hidden="true"></span>
              <span class="option-copy">
                <span class="option-title">Push Notifications</span>
                <span class="option-note">Real-time alerts directly on your device.</span>
              </span>
            </label>
          </div>
        </fieldset>
      </div>

      <button type="submit">Submit</button>
      <p class="status" id="status-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("notification-form");
    const statusMessage = document.getElementById("status-message");

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const formData = new FormData(form);
      const selection = formData.get("notificationPreference");
      statusMessage.textContent = `Preference saved: ${selection}.`;
    });
  </script>
</body>
</html>
